    "MCP サーバーに接続できませんでした。しばらくしてからもう一度お試しください。",
  "settings.mcp.failureAdvice.config_invalid":
    "MCP のコマンド、引数、サーバーアドレス、環境変数を確認してください。設定を修正してから状態を更新してください。",
  "settings.mcp.failureAdvice.runtime_unavailable":
    "この MCP を実行しているデバイスで、必要なランタイムをインストールまたは設定し、ZCode が起動コマンドを見つけられるようにしてください。",
  "settings.mcp.failureAdvice.process_start_failed":
    "この MCP を実行しているデバイスで、起動コマンド、作業ディレクトリ、スクリプトのパス、実行権限を確認してください。Python の依存関係は、そのコマンドのインタプリターまたは仮想環境で、プラグインの requirements ファイル（requirements.txt など）からインストールしてください。Node の MCP では Node.js とパッケージの依存関係を確認してください。環境を修正してから更新してください。",
  "settings.mcp.failureAdvice.network_unreachable":
    "MCP を実行しているデバイスからサーバーアドレスに接続できるか確認してください。プロキシ、VPN、ファイアウォール、ポートの設定も確認してください。",
  "settings.mcp.failureAdvice.connection_timeout":
    "サーバーが起動していることを確認し、ネットワークとプロキシ、サーバーログを確認してください。起動が遅い場合は、接続タイムアウトの設定を確認してください。",
  "settings.mcp.failureAdvice.protocol_negotiation_failed":
    "サーバーが対応する MCP バージョンを確認してください。古いサーバーの場合は、設定で Legacy モードを試してください。通常のログをプロトコル出力に書き込まないようにしてください。",
  "settings.mcp.failureAdvice.tool_list_failed":
    "サーバーログを確認し、tools/list が有効な MCP ツール一覧を返すことを確認してから、状態を更新してください。",
  "settings.mcp.failureAdvice.unexpected_disconnect":
    "下のエラーとサーバーログを確認してください。プロセスの終了、依存関係の不足、接続の中断がないか確認してから、状態を更新してください。",
  "settings.mcp.failureAdvice.oauth_authorization_failed":
    "この MCP サーバーの認可リンクをもう一度開き、ブラウザーで認可を完了してから ZCode に戻り、状態を更新してください。",
  "settings.mcp.failureAdvice.official_origin_untrusted":
    "プラグインとサーバーアドレスが信頼できる設定に由来するか確認してください。セキュリティチェックを無効にしたり、不明なアドレスにログイン情報を入力したりしないでください。",
  "settings.mcp.failureAdvice.not_authenticated":
    "ZCode にサインインしてから MCP の状態を更新してください。アカウントがサインイン済みに見える場合は、サインインし直してください。",
  "settings.mcp.failureAdvice.coding_plan_required":
    "モデル設定で、アカウントの Coding Plan と選択中のチームまたはプロジェクトを確認してください。利用可能になったことを確認してから更新してください。",
  "settings.mcp.failureAdvice.server_not_found":
    "サーバーアドレス、パス、プラグインのバージョンを確認してください。アドレスがプラグイン由来の場合は、更新を確認するかプラグイン提供元に連絡してください。",
  "settings.mcp.failureAdvice.server_unavailable":
    "しばらくしてから状態を更新してください。問題が続く場合は、下のエラーとリクエスト ID（ある場合）をサービス提供元に共有してください。",
  "settings.mcp.failureAdvice.rate_limited":
    "再試行を繰り返さないでください。レート制限が解除されてから更新し、アカウントのリクエスト上限を確認してください。",
  "settings.mcp.failureAdvice.server_internal_error":
    "しばらくしてからもう一度お試しください。問題が続く場合は、下のエラーとリクエスト ID（ある場合）をサービス提供元に共有してください。",
  "settings.mcp.failureAdvice.protocol_error":
    "クライアントとサーバーの MCP バージョンを確認し、サーバーログのプロトコルエラーを確認してください。必要に応じてプラグインまたはサーバーを更新してください。",
  "settings.mcp.failureAdvice.status_unavailable":
    "状態を更新してください。それでも取得できない場合は、Agent を再起動し、該当デバイスのログを確認してください。",
  "settings.mcp.failureAdvice.connection_failed":
    "下のエラーを手がかりに、サーバーが起動していること、設定とネットワークが正しいことを確認してください。修正してから状態を更新してください。",
