  "settings.modelProvider.fieldHelp": "{field}について",
  "settings.modelProvider.help.contextWindow":
    "モデルが一度に処理できるコンテキストの容量（トークン単位）です。ZCode はこの値を使ってコンテキストを管理します。\nモデルの実際の上限を超えないようにしてください。",
  "settings.modelProvider.help.maxOutputTokens":
    "1 回のモデルリクエストで生成できるトークンの最大数です。\nモデルの実際の上限を超えないようにしてください。",
  "settings.modelProvider.help.inputModalities":
    "モデルが受け取れるコンテンツの種類を設定します:\n\n- **テキスト**: テキストを受け取ります。必須です。\n- **画像**: 画像を受け取ります。\n- **動画**: 動画を受け取ります。\n- **PDF**: PDF ドキュメントを直接受け取ります。",
  "settings.modelProvider.help.outputModalities":
    "モデルの応答のコンテンツの種類です。現在はテキストのみサポートしています。",
  "settings.modelProvider.help.capabilities":
    "- **構造化出力**: 出力のフィールド、型、構造に対する JSON Schema による制約をサポートします。\n- **ネイティブ Web 検索**: モデル API に組み込まれた Web 検索機能をサポートします。\n- **会話途中のシステムメッセージ**: 会話の途中でシステム指示を挿入できます。\n\nモデルがサポートしていない機能は有効にしないでください。",
  "settings.modelProvider.help.reasoningLevelsOrdered":
    "チャットで使用できる推論レベルを設定します。**推論の強度が低い順から高い順に並べる必要があります**。\nモデルがサポートしていない推論レベルは設定しないでください。",
  "settings.modelProvider.help.reasoningLevelMapping":
    "CEL 式を使って、現在の推論レベル `reasoningLevel` をモデル API のリクエストフィールドにマッピングします。式が返す JSON オブジェクトは、送信するリクエストボディにマージされます。",
  "settings.modelProvider.help.advanced":
    "**MFJS tool schema**: Moonshot Flavored JSON Schema との互換性を有効にします。主に Moonshot の Kimi モデル API で使用されます。モデル API がこの形式を必要とする場合にのみ有効にしてください。",
  "settings.modelProvider.help.followRecommendedConfig":
    "モデル ID、Base URL、API 形式をもとに推奨構成を照合します。ZCode は推奨構成を継続的に更新し、自動的に同期します。\n設定を手動で変更すると、その設定は手動管理となり、推奨構成の更新に追従しなくなります。その他の設定は引き続きスマート構成で管理されます。",
